-- 읽기 전용. 설치 전과 TP1-01·02 설치 직후 F1~F7을 비교한다. 계정 등록 이후에는 승인된 10명 추가분을 별도 대조한다.
WITH expected(v) AS(SELECT value FROM jsonb_array_elements($patches$[["teacher_roster.snapshot(workhub_private.actor_context)","9ab45dbd5cd2b0ed95c81847a768123d","3483ac7129703e301e92328160c1ca17","teacher_roster.links","teacher_pilot.effective_links",1],["teacher_roster.evaluate(workhub_private.actor_context,jsonb)","7d4b14c863560e8a589ed129bbf1e63e","b79b5691319cf626c739f1da19ffb022","teacher_roster.links","teacher_pilot.effective_links",1],["teacher_roster.bridge(workhub_private.actor_context,text)","95df4285ed96b896840859e6a6c776c5","5c95f22fbd3100766f6cd72a537f35ce","teacher_roster.links","teacher_pilot.bridge_links",2],["public.workhub_teacher_roster_published(text,text)","a4e94bbd62c65509d32a783565ffdfc3","be1b2324170757cf80a0468e57d70c27","teacher_roster.links","teacher_pilot.effective_links",1],["workhub_private.p6_service_member(uuid,text)","75949615caeba44db264651a075abf16","dc95ec51b25951a55ebff2ab4dda86fb","workhub_private.member_actor","teacher_pilot.actor",1],["public.workhub_ai_threads_list(text,text,text)","0e7a3a727f499507cd2f5f66b85453a2","efe62caa5773b3f8575750ecdb6bca81","workhub_private.member_actor","teacher_pilot.actor",1],["public.workhub_ai_thread_get(text,text,text)","26d81b4dff4d7056591514a5a89ec18a","f2c04fcaebc4b4cc39e344b3d82a6e75","workhub_private.member_actor","teacher_pilot.actor",1],["public.workhub_ai_confirm_task(text,jsonb,text)","662599ef7f35dcda61d64500dce5c67c","0d21baf8e56ea495f1144059ca8e9d65","workhub_private.member_actor","teacher_pilot.actor",1],["public.workhub_ai_policy_thread_get(text,text,text)","624ae1c4ae7a973a114f5cfdd4cc4583","aa19d4fae256a6f51dc6b60a37981059","workhub_private.member_actor","teacher_pilot.actor",1]]$patches$::jsonb)), rows(no,item,status,value) AS(
SELECT 'TP1-00-01','TR1·OP1·P10 선행 설치',CASE WHEN to_regclass('teacher_roster.links') IS NOT NULL AND to_regclass('workhub.participant_grants') IS NOT NULL AND to_regclass('workhub.ai_school_policies') IS NOT NULL THEN 'ok' ELSE 'FAIL' END,NULL::text
UNION ALL SELECT 'TP1-00-02','TP1 설치 유무','info',coalesce(to_regnamespace('teacher_pilot')::text,'미설치')
UNION ALL SELECT 'TP1-00-03','기존 함수 원문 9개',CASE WHEN count(*)=9 AND bool_and(coalesce(md5(replace(p.prosrc,E'\r\n',E'\n')) IN(e.v->>1,e.v->>2) AND p.proowner='postgres'::regrole,false)) THEN 'ok' ELSE 'FAIL' END,count(*)::text FROM expected e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.v->>0)
UNION ALL SELECT 'TP1-00-04','명부·기본표 현황','info',jsonb_build_object('teachers',(SELECT count(*) FROM teacher_roster.teachers),'plans',(SELECT count(*) FROM teacher_roster.plans),'links',(SELECT count(*) FROM teacher_roster.links),'classes',(SELECT coalesce(sum(jsonb_array_length(body->'classes')),0) FROM teacher_roster.plans WHERE state='published'),'lessons',(SELECT coalesce(sum(jsonb_array_length(body->'lessons')),0) FROM teacher_roster.plans WHERE state='published'))::text
UNION ALL SELECT 'F1','public.users','compare',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(v::text,chr(10) ORDER BY v::text),'')))::text FROM(SELECT to_jsonb(t) v FROM public.users t) f
UNION ALL SELECT 'F2','workhub.memberships','compare',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(v::text,chr(10) ORDER BY v::text),'')))::text FROM(SELECT to_jsonb(t) v FROM workhub.memberships t) f
UNION ALL SELECT 'F3','workhub.membership_roles','compare',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(v::text,chr(10) ORDER BY v::text),'')))::text FROM(SELECT to_jsonb(t) v FROM workhub.membership_roles t) f
UNION ALL SELECT 'F4','teacher_roster.plans','compare',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(v::text,chr(10) ORDER BY v::text),'')))::text FROM(SELECT to_jsonb(t) v FROM teacher_roster.plans t) f
UNION ALL SELECT 'F5','teacher_roster.links','compare',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(v::text,chr(10) ORDER BY v::text),'')))::text FROM(SELECT to_jsonb(t)-'tp1_end_date' v FROM teacher_roster.links t) f
UNION ALL SELECT 'F6','workhub.staff_assignments','compare',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(v::text,chr(10) ORDER BY v::text),'')))::text FROM(SELECT to_jsonb(t)-'tp1_cancelled' v FROM workhub.staff_assignments t) f
UNION ALL SELECT 'F7','workhub.ai_school_policies','compare',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(v::text,chr(10) ORDER BY v::text),'')))::text FROM(SELECT to_jsonb(t) v FROM workhub.ai_school_policies t) f
) SELECT * FROM rows ORDER BY no;
